import sys
sys.setrecursionlimit(10**8)
class Flow:
    def __init__(self, n):
        self.n = n
        self.mat = [[0]*n for _ in range(n)]
    def upd(self, a, b, cap):
        self.mat[a][b] = cap
    def dfs(self, s, t, f, used, aux0, bad):
        used[s] = True
        if s == t:
            return f
        rng = self.n - 1 if (aux0 and s == bad) else self.n
        for i in range(rng):
            if not used[i] and self.mat[s][i] > 0:
                ret = self.dfs(i, t, min(f, self.mat[s][i]), used, aux0, bad)
                if ret:
                    self.mat[s][i] -= ret
                    self.mat[i][s] += ret
                    return ret
        return 0
    def max_flow(self, s, t, aux0, bad):
        flow = 0
        INF = 10**20
        while True:
            used = [False]*self.n
            pushed = self.dfs(s, t, INF, used, aux0, bad)
            if not pushed:
                break
            flow += pushed
        return flow

